(()=>{const fit=()=>{const s=Math.min(innerWidth/1920,innerHeight/1080);document.documentElement.style.setProperty('--scale',s);document.documentElement.style.setProperty('--study-scale',s);};fit();addEventListener('resize',fit);let tick=0;const observer=typeof IntersectionObserver==='function'?new IntersectionObserver(es=>es.forEach(e=>document.body.classList.toggle('outside-view',!e.isIntersecting))):null;observer?.observe(document.documentElement);setInterval(()=>{if(document.hidden)return;tick++;const clock=document.getElementById('clock');if(clock)clock.textContent='10:'+String(20+Math.floor(tick/60)%40).padStart(2,'0')+':'+String(tick%60).padStart(2,'0');const energy=document.getElementById('energy-value');if(energy)energy.textContent=(65820+tick*7).toLocaleString('en-US');const swaps=document.getElementById('swap-value');if(swaps)swaps.textContent=(1732+Math.floor(tick/3)).toLocaleString('en-US');const vehicles=document.getElementById('vehicle-value');if(vehicles)vehicles.textContent=(864+Math.floor(tick/6)).toLocaleString('en-US');},2000);})();
